DROP VIEW IF EXISTS reports.vwbrandmedication;
CREATE VIEW reports.vwbrandmedication AS SELECT bm.id, bm.name, bm.code, bm.manufacturer, bm.dosage_form, bm.usage_instructions, bm.storage_requirements, bm.price, bm.currency, bm.expires_after_opening, bm.expires_after_opening_value, bm.expires_after_opening_unit, bm.single_patient_use, bm.high_cost_medication, bm.cost_category, bm.roa, bm.uom_group_id, bm.uom_group_unit_id, bm.is_active, bm.created_by, bm.created_date, bm.last_modified_by, bm.last_modified_date, bm.billing_rule_id FROM public.brand_medication bm;
GRANT SELECT ON reports.vwbrandmedication TO report_user;
